@@ -0,0 +1,20 @@
+// API keys and role-based access: viewer < cook < manager.
+import { AppError } from "../errors.js";
+
+/** Roles in ascending order of permission. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+/** Returns the API key entry for `key`, or throws AppError unauthorized. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || !key) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === key);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Ensures `apiKey` has at least `requiredRole`, or throws AppError forbidden. */
+export function authorize(apiKey, requiredRole) {
+  const have = ROLES.indexOf(apiKey?.role);
+  const need = ROLES.indexOf(requiredRole);
+  if (have < 0 || need < 0 || have < need) throw new AppError("forbidden");
+}
